 <p/>
 Rather than interacting directly with a Cleaner object, generally see the {@code clean} methods in {@link org.jsoup.Jsoup}.
 */
public class Cleaner {
    private Whitelist allowedTagsAndAttributes;

    /**
     Create a new cleaner, that sanitizes documents using the supplied whitelist.
     @param whitelist white-list to clean with
     */
    public Cleaner(Whitelist whitelist) {
        Validate.notNull(whitelist);
        this.allowedTagsAndAttributes = whitelist;
    }

    /**
     Creates a new, clean document, from the original dirty document, containing only elements allowed by the whitelist.
     The original document is not modified. Only elements from the dirt document's <code>body</code> are used.
     @param dirtyDocument Untrusted base document to clean.
     @return cleaned document.
     */
    public Document clean(Document dirtyDocument) {
        Validate.notNull(dirtyDocument);

        Document resultingDoc = Document.createShell(dirtyDocument.baseUri());
        if (dirtyDocument.body() != null) // frameset documents won't have a body. the clean doc will have empty body.
            copySafeNodes(dirtyDocument.body(), resultingDoc.body());

        return resultingDoc;
    }

    /**
     Determines if the input document is valid, against the whitelist. It is considered valid if all the tags and attributes
     in the input HTML are allowed by the whitelist.
     <p/>
     This method can be used as a validator for user input forms. An invalid document will still be cleaned successfully
     using the {@link #clean(Document)} document. If using as a validator, it is recommended to still clean the document
     to ensure enforced attributes are set correctly, and that the output is tidied.
     @param dirtyDocument document to test
     @return true if no tags or attributes need to be removed; false if they do
     */
    public boolean isValid(Document dirtyDocument) {
        Validate.notNull(dirtyDocument);

        Document inspectDoc = Document.createShell(dirtyDocument.baseUri());
        int removedCount = copySafeNodes(dirtyDocument.body(), inspectDoc.body());
        return removedCount == 0;
    }

    /**
     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
     */
    private int copySafeNodes(Element root, Element destination) {
        List<Node> childrenOfRoot = root.childNodes();
        int removedCount = 0;

        int idx = 0;
        while (idx < childrenOfRoot.size()) {
            Node node = childrenOfRoot.get(idx);
            if (node instanceof Element) {
                Element elem = (Element) node;

                if (allowedTagsAndAttributes.isSafeTag(elem.tagName())) { // safe, clone and copy safe attrs
                    ElementMeta metaInfo = createSafeElement(elem);
                    Element copiedChild = metaInfo.el;
                    destination.appendChild(copiedChild);

                    removedCount += metaInfo.numAttribsDiscarded;
                    removedCount += copySafeNodes(elem, copiedChild);
                } else {
                    removedCount = removedCount + 1;
                    removedCount += copySafeNodes(elem, destination);
                }
            } else if (node instanceof TextNode) {
                TextNode originalText = (TextNode) node;
                TextNode copiedText = new TextNode(originalText.getWholeText(), node.baseUri());
                destination.appendChild(copiedText);
            }
            idx++;
        }
        return removedCount;


    }

    private ElementMeta createSafeElement(Element sourceEl) {
        String tagName = sourceEl.tagName();
        Attributes filteredAttrs = new Attributes();
        Element safeElement = new Element(Tag.valueOf(tagName), sourceEl.baseUri(), filteredAttrs);
        int attrDiscards = 0;

        Attributes originalAttrs = sourceEl.attributes();
        for (Attribute attr : originalAttrs) {
            if (!allowedTagsAndAttributes.isSafeAttribute(tagName, sourceEl, attr)) {
                attrDiscards++;
            } else {
                filteredAttrs.put(attr);
            }
        }
        Attributes mustHaveAttrs = allowedTagsAndAttributes.getEnforcedAttributes(tagName);
        filteredAttrs.addAll(mustHaveAttrs);

        return new ElementMeta(safeElement, attrDiscards);
    }

    private static class ElementMeta {
        Element el;
        int numAttribsDiscarded;

        ElementMeta(Element el, int numAttribsDiscarded) {
            this.el = el;
            this.numAttribsDiscarded = numAttribsDiscarded;
